-- PT108-S3-Q17. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT108-S3-Q17$batch03$ AND q.stimulus=$batch03$Radial keratotomy (RK), a surgery that is designed to reshape the cornea so that light focuses correctly on the retina, is supposed to make eyeglasses or contact lenses that correct for nearsightedness unnecessary. Yet a study of patients who have undergone RK shows that some of them still need to wear glasses or contact lenses.$batch03$ AND q.prompt=$batch03$Each of the following, if true, would help to resolve the apparent discrepancy in the information above EXCEPT:$batch03$ AND q.correct_choice=$batch03$E$batch03$) THEN RAISE EXCEPTION 'Question changed: PT108-S3-Q17'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT108-S3-Q17$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT108-S3-Q17'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT108-S3-Q17$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$RK is supposed to make glasses and contacts unnecessary for nearsighted people.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Some RK patients still need glasses or contacts?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Frame: "This patient still needs lenses because..." Working answers describe a way the surgery can fall short or create a new vision problem. The answer will say nothing about what happens to RK patients' eyes.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Four choices give a reason some patients still need lenses. The answer will not.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT108-S3-Q17$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$The eye overcorrects while healing and becomes farsighted. That patient now needs lenses for a new problem.$batch03$), ($batch03$B$batch03$, $batch03$RK works less well on severe nearsightedness. Severely nearsighted patients may be left needing lenses.$batch03$), ($batch03$C$batch03$, $batch03$Uneven healing leaves the two eyes different, which only lenses can fix.$batch03$), ($batch03$D$batch03$, $batch03$Uneven healing can cause astigmatism that requires lenses, even in patients who started with mild nearsightedness.$batch03$), ($batch03$E$batch03$, $batch03$This compares RK patients with people who skipped surgery, before surgery. Being equally nearsighted beforehand says nothing about why some patients need lenses afterward.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT108-S3-Q17$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
